//! SBE flyweight codec generated by sbe-tool 1.40.2.
//!
//! Codegen is build-time (the vendored crate). Filling the flyweight is inside
//! `serialize_into`. Wire order for signal is fixed fields, then the legs group,
//! then symbol and venue. The domain struct stays strings-before-legs.
//! `nested_table` is not an SBE body. There is no compliance decoder.
//! Logged version is the generator release, not the generated crate's 0.1.0.

use crate::data::{Fixture, Signal, SignalLeg, TableRow};
use anyhow::{anyhow, Context, Result};
use benchmark_v2::message_header_codec::{MessageHeaderDecoder, ENCODED_LENGTH};
use benchmark_v2::signal_codec::decoder::SignalDecoder;
use benchmark_v2::signal_codec::encoder::{LegsEncoder, SignalEncoder};
use benchmark_v2::signal_codec::SBE_BLOCK_LENGTH as SIGNAL_BLOCK;
use benchmark_v2::signal_codec::SBE_TEMPLATE_ID as SIGNAL_TEMPLATE;
use benchmark_v2::table_codec::decoder::TableDecoder;
use benchmark_v2::table_codec::encoder::TableEncoder;
use benchmark_v2::table_codec::SBE_BLOCK_LENGTH as TABLE_BLOCK;
use benchmark_v2::table_codec::SBE_TEMPLATE_ID as TABLE_TEMPLATE;
use benchmark_v2::{Decoder, ReadBuf, Reader, WriteBuf};

use super::BenchSerializer;

const SBE_VERSION: &str = "1.40.2";
const LEG_BLOCK: usize = 16;
const GROUP_HEADER: usize = 4;

pub struct SbeSer {
    kind: &'static str,
}

impl Default for SbeSer {
    fn default() -> Self {
        Self { kind: "signal" }
    }
}

fn table_size(row: &TableRow) -> usize {
    ENCODED_LENGTH
        + TABLE_BLOCK as usize
        + 4
        + row.f_str_0.len()
        + 4
        + row.f_str_1.len()
}

fn signal_size(sig: &Signal) -> usize {
    ENCODED_LENGTH
        + SIGNAL_BLOCK as usize
        + GROUP_HEADER
        + sig.legs.len() * LEG_BLOCK
        + 4
        + sig.symbol.len()
        + 4
        + sig.venue.len()
}

fn utf8_at<'a>(dec: &impl Reader<'a>, coords: (usize, usize)) -> Result<String> {
    let bytes = dec.get_buf().get_slice_at(coords.0, coords.1);
    Ok(String::from_utf8(bytes.to_vec()).context("sbe utf8")?)
}

fn encode_table(row: &TableRow, out: &mut Vec<u8>) -> Result<()> {
    let start = out.len();
    out.resize(start + table_size(row), 0);
    let buf = WriteBuf::new(&mut out[start..]);
    let enc = TableEncoder::default().wrap(buf, ENCODED_LENGTH);
    let mut header = enc.header(0);
    let mut enc = header.parent().map_err(|e| anyhow!("sbe table header: {e}"))?;
    enc.f_float_0(row.f_float_0)
        .f_float_1(row.f_float_1)
        .f_float_2(row.f_float_2)
        .f_float_3(row.f_float_3)
        .f_float_4(row.f_float_4)
        .f_float_5(row.f_float_5)
        .f_float_6(row.f_float_6)
        .f_float_7(row.f_float_7)
        .f_float_8(row.f_float_8)
        .f_float_9(row.f_float_9)
        .f_float_10(row.f_float_10)
        .f_float_11(row.f_float_11)
        .f_float_12(row.f_float_12)
        .f_float_13(row.f_float_13)
        .f_float_14(row.f_float_14)
        .f_float_15(row.f_float_15)
        .f_int_0(row.f_int_0)
        .f_int_1(row.f_int_1)
        .f_int_2(row.f_int_2)
        .f_int_3(row.f_int_3)
        .f_str_0(&row.f_str_0)
        .f_str_1(&row.f_str_1);
    let limit = benchmark_v2::Encoder::get_limit(&enc);
    drop(enc);
    out.truncate(start + limit);
    Ok(())
}

fn encode_signal(sig: &Signal, out: &mut Vec<u8>) -> Result<()> {
    let start = out.len();
    out.resize(start + signal_size(sig), 0);
    let buf = WriteBuf::new(&mut out[start..]);
    let enc = SignalEncoder::default().wrap(buf, ENCODED_LENGTH);
    let mut header = enc.header(0);
    let mut enc = header
        .parent()
        .map_err(|e| anyhow!("sbe signal header: {e}"))?;
    enc.seq(sig.seq)
        .ts(sig.ts)
        .price_mantissa(sig.price_mantissa)
        .qty(sig.qty)
        .flags(sig.flags);
    let count = u16::try_from(sig.legs.len()).context("sbe leg count")?;
    let mut legs = enc.legs_encoder(count, LegsEncoder::default());
    for leg in &sig.legs {
        legs.advance()
            .map_err(|e| anyhow!("sbe leg advance: {e}"))?
            .context("sbe leg count exceeded")?;
        legs.leg_id(leg.leg_id).leg_qty(leg.leg_qty).leg_pad(0);
    }
    let mut enc = legs.parent().map_err(|e| anyhow!("sbe legs parent: {e}"))?;
    enc.symbol(&sig.symbol).venue(&sig.venue);
    let limit = benchmark_v2::Encoder::get_limit(&enc);
    drop(enc);
    out.truncate(start + limit);
    Ok(())
}

fn decode_table_at(data: &[u8], offset: usize) -> Result<(TableRow, usize)> {
    let header = MessageHeaderDecoder::default().wrap(ReadBuf::new(data), offset);
    let template = header.template_id();
    if template != TABLE_TEMPLATE {
        anyhow::bail!("sbe: table template {template} at {offset}");
    }
    let mut dec = TableDecoder::default().header(header, offset);
    let row = TableRow {
        f_float_0: dec.f_float_0(),
        f_float_1: dec.f_float_1(),
        f_float_2: dec.f_float_2(),
        f_float_3: dec.f_float_3(),
        f_float_4: dec.f_float_4(),
        f_float_5: dec.f_float_5(),
        f_float_6: dec.f_float_6(),
        f_float_7: dec.f_float_7(),
        f_float_8: dec.f_float_8(),
        f_float_9: dec.f_float_9(),
        f_float_10: dec.f_float_10(),
        f_float_11: dec.f_float_11(),
        f_float_12: dec.f_float_12(),
        f_float_13: dec.f_float_13(),
        f_float_14: dec.f_float_14(),
        f_float_15: dec.f_float_15(),
        f_int_0: dec.f_int_0(),
        f_int_1: dec.f_int_1(),
        f_int_2: dec.f_int_2(),
        f_int_3: dec.f_int_3(),
        f_str_0: String::new(),
        f_str_1: String::new(),
    };
    let c0 = dec.f_str_0_decoder();
    let f_str_0 = utf8_at(&dec, c0)?;
    let c1 = dec.f_str_1_decoder();
    let f_str_1 = utf8_at(&dec, c1)?;
    let end = Decoder::get_limit(&dec);
    Ok((
        TableRow {
            f_str_0,
            f_str_1,
            ..row
        },
        end,
    ))
}

fn decode_signal_at(data: &[u8], offset: usize) -> Result<(Signal, usize)> {
    let header = MessageHeaderDecoder::default().wrap(ReadBuf::new(data), offset);
    let template = header.template_id();
    if template != SIGNAL_TEMPLATE {
        anyhow::bail!("sbe: signal template {template} at {offset}");
    }
    let dec = SignalDecoder::default().header(header, offset);
    let seq = dec.seq();
    let ts = dec.ts();
    let price_mantissa = dec.price_mantissa();
    let qty = dec.qty();
    let flags = dec.flags();
    let mut legs_dec = dec.legs_decoder();
    let mut legs = Vec::with_capacity(legs_dec.count() as usize);
    while legs_dec
        .advance()
        .map_err(|e| anyhow!("sbe legs: {e}"))?
        .is_some()
    {
        legs.push(SignalLeg {
            leg_id: legs_dec.leg_id(),
            leg_qty: legs_dec.leg_qty(),
            leg_pad: legs_dec.leg_pad(),
        });
    }
    let mut dec = legs_dec
        .parent()
        .map_err(|e| anyhow!("sbe signal parent: {e}"))?;
    let c0 = dec.symbol_decoder();
    let symbol = utf8_at(&dec, c0)?;
    let c1 = dec.venue_decoder();
    let venue = utf8_at(&dec, c1)?;
    let end = Decoder::get_limit(&dec);
    Ok((
        Signal {
            seq,
            ts,
            price_mantissa,
            qty,
            flags,
            symbol,
            venue,
            legs,
        },
        end,
    ))
}

fn walk<T>(data: &[u8], one: impl Fn(&[u8], usize) -> Result<(T, usize)>) -> Result<Vec<T>> {
    let mut off = 0;
    let mut rows = Vec::new();
    while off < data.len() {
        let (row, next) = one(data, off)?;
        if next <= off {
            anyhow::bail!("sbe: no progress at {off}");
        }
        rows.push(row);
        off = next;
    }
    if rows.is_empty() {
        anyhow::bail!("sbe: empty payload");
    }
    Ok(rows)
}

fn pack_tables(kind: &str, rows: Vec<TableRow>) -> Fixture {
    if kind == "table_project" {
        return Fixture::Projected(rows.iter().map(|r| r.f_float_0).collect());
    }
    let wrapped: Vec<_> = rows.into_iter().map(Fixture::Table).collect();
    if wrapped.len() == 1 {
        wrapped.into_iter().next().unwrap()
    } else {
        Fixture::Rows(wrapped)
    }
}

fn pack_signals(rows: Vec<Signal>) -> Fixture {
    let wrapped: Vec<_> = rows.into_iter().map(Fixture::Signal).collect();
    if wrapped.len() == 1 {
        wrapped.into_iter().next().unwrap()
    } else {
        Fixture::Rows(wrapped)
    }
}

impl SbeSer {
    fn encode_one(&self, fixture: &Fixture, out: &mut Vec<u8>) -> Result<()> {
        match fixture {
            Fixture::Table(row) | Fixture::TableProject(row) => encode_table(row, out),
            Fixture::Signal(sig) => encode_signal(sig, out),
            Fixture::Rows(rows) => {
                for row in rows {
                    self.encode_one(row, out)?;
                }
                Ok(())
            }
            other => Err(anyhow!("sbe: cannot encode {}", other.name())),
        }
    }
}

impl BenchSerializer for SbeSer {
    fn name(&self) -> &'static str {
        "sbe"
    }
    fn version(&self) -> &'static str {
        SBE_VERSION
    }
    fn native_kind(&self) -> super::NativeKind {
        super::NativeKind::Message
    }
    fn supports(&self, test_data_name: &str) -> bool {
        matches!(test_data_name, "table" | "table_project" | "signal")
    }
    fn prepare(&mut self, fixture: &Fixture) -> Result<()> {
        let kind = fixture.name();
        if !self.supports(kind) {
            return Err(anyhow!("sbe: no body for {kind}"));
        }
        self.kind = kind;
        Ok(())
    }
    fn serialize_into(&mut self, fixture: &Fixture, out: &mut Vec<u8>) -> Result<()> {
        self.encode_one(fixture, out)
    }
    fn serialize_fixtures(&mut self, fixtures: &[Fixture], out: &mut Vec<u8>) -> Result<()> {
        for fx in fixtures {
            self.encode_one(fx, out)?;
        }
        Ok(())
    }
    fn deserialize_bytes(&mut self, data: &[u8]) -> Result<Fixture> {
        match self.kind {
            "table" | "table_project" => {
                Ok(pack_tables(self.kind, walk(data, decode_table_at)?))
            }
            "signal" => Ok(pack_signals(walk(data, decode_signal_at)?)),
            other => Err(anyhow!("sbe: unsupported kind {other}")),
        }
    }
}

